{
  "nodeId": "64 lowercase ASCII hex (see Lexical Token Rules)",
  "timestamp": "see Timestamp Format",
  "scope": "string",
  "issuer": {
    "issuerId": "string",
    "keyId": "string"
  },
  "agent": {
    "agentId": "string",
    "version": "string"
  },
  "actor": {
    // OPTIONAL -- see below
    "actorId": "string",
    "authContext": "string"
  },
  "action": {
    "type": "string",
    "inputHash": "see Payload Hash Format",
    "outputHash": "see Payload Hash Format"
  },
  "parents": ["nodeId"],
  "profile": "string",        // OPTIONAL -- see Profile Identifiers
  "signature": "canonical base64 (RFC 4648 Sec 3.5)"
}
